//! Whole-group mutations expanded into the ordinary update AST.
use crate::{
    Attr, BuildError, DerivedOnly, EncodeContext, PathSegment, Record, Required, Variants,
    condition::Operand,
    update::{Action, ActionNode, SetNode},
};

/// Binds a record to its single flattened variant group. Generated by `Record`.
/// Manual records supply the discriminator's position in `Record::SCHEMA.fields`.
pub trait FlattenedVariants<V: Variants>: Record {
    const FIELD: usize;
}

pub(crate) fn expand<R: FlattenedVariants<V>, V: Variants + 'static>(
    field: Attr<R, V::Tag, Required, DerivedOnly>,
    value: V,
) -> Action<R> {
    let descriptor = field.validate();
    Action::expand(move || {
        let field = descriptor?;
        let invalid = || BuildError::OperationConstraint {
            code: "invalid_flattened_variant",
        };
        if field.index != R::FIELD
            || field.name != V::TAG
            || field.index == R::SCHEMA.primary.partition
            || Some(field.index) == R::SCHEMA.primary.sort
            || !V::ATTRIBUTES.contains(&V::TAG)
            || R::SCHEMA
                .fields
                .iter()
                .any(|other| other.index != field.index && V::ATTRIBUTES.contains(&other.name))
        {
            return Err(invalid());
        }
        let mut item = value.encode_map(&mut EncodeContext::new(R::SCHEMA.name))?;
        if !matches!(
            item.get(V::TAG),
            Some(aws_sdk_dynamodb::types::AttributeValue::S(_))
        ) || item
            .keys()
            .any(|name| !V::ATTRIBUTES.contains(&name.as_str()))
        {
            return Err(invalid());
        }
        let mut actions = Vec::new();
        for (i, name) in V::ATTRIBUTES.iter().enumerate() {
            if name.is_empty() || V::ATTRIBUTES[..i].contains(name) {
                return Err(invalid());
            }
            let target = vec![PathSegment::Attribute((*name).into())].into();
            actions.push(match item.remove(*name) {
                Some(value) => ActionNode::NestedSet {
                    target,
                    value: SetNode::Operand(Operand::Value(value)),
                },
                None => ActionNode::NestedRemove { target },
            });
        }
        Ok(actions)
    })
}
